suppressPackageStartupMessages(pacman::p_load(DBI, dplyr, RMariaDB, RSQLite))



check_table_existence <- function(dbc, table) {
  # Check for table existence, stop script if non-existent
  if (!dbExistsTable(dbc, table)) {
    stop(paste0("Table ", table, " not yet in database. Execute createDB script before proceeding."), 
         call. = FALSE)
  }
}

blank_to_na <- function(d) {
  # Generated by Claude to replace empty strings with NULL values
  chars <- sapply(d, is.character)
  d[chars] <- lapply(d[chars], function(x) { x <- trimws(x); x[x == ""] <- NA; x })
  d
}

insert_data <- function(dbc, table, data) {
  # try catch data insertion
  tryCatch({
    dbWithTransaction(
      dbc, 
      dbWriteTable(dbc, table, df, append = TRUE, row.names = FALSE)
    )
    TRUE
  }, error = function(e) {
    message("Load failed for '", table, "': ", conditionMessage(e))
    FALSE
  })
}

